phase('FactCheck')
const facts = (await chunked(validated.slice(0, topN).map((i) => () => agent(
  "CRITICAL: return ONLY the JSON for the schema. Do NOT invoke any Skill, do NOT run apply/merge scripts, do NOT write or edit ledger/report files, do NOT spawn sub-agents — the pipeline applies your output. Independent fact-checker. Verify the single most load-bearing demand claim behind a business idea against a PRIMARY or authoritative source (govt scheme text, trade statistics, regulator, official filing, franchise disclosure, the marketplace itself). Do NOT trust marketing blogs or the ideas own pitch.\n" + 'IDEA: ' + i.name + '\nCLAIM TO CHECK: ' + ((i.validation && i.validation.demand_evidence) || i.the_insight) + "\nSearch for the original source. Return 1-2 fact_checks with verified = \"true\" ONLY if a primary source confirms it; \"false\" if contradicted; \"unclear\" if you cannot confirm." + ' Set name to exactly ' + JSON.stringify(i.name) + '.',
  { label: 'fact:' + String(i.name || '').slice(0, 24), phase: 'FactCheck', model: 'haiku', schema: FC_SCHEMA }
)), 3)).filter(Boolean)
const factByName = new Map(facts.map((f) => [f.name, f.fact_checks]))
for (const i of validated) if (factByName.has(i.name)) i.fact_checks = factByName.get(i.name)

const scored_ideas = validated.map((i) => ({
  name: i.name, shape: i.shape, source_channel: i.source_channel, one_liner: i.one_liner,
  the_insight: i.the_insight, monetization: i.monetization, composite: i.composite,
  validation: i.validation, fact_checks: i.fact_checks || [],
}))
log(`done: ${scored_ideas.length} scored, top ${topN} fact-checked`)
return { scored_ideas, signal_count: allSignals.length, idea_count: ideas.length, channels: ["physical-trade-import-export","manufacturing-msme","markets-trading-fintech","franchise-distribution-licensing","content-media-brands"] }